-- Celu Piezaz Dot Com — Catálogo maestro v2 (109 modelos).
-- Idempotente; ejecutar después de 004_tiendas_inventario.sql.

create extension if not exists unaccent;


-- Modelos canónicos y alias de búsqueda.

-- Productos maestros únicos por modelo + tipo + variante.
select pm.id,pt.id,pv.id,
concat(pm.brand,' · ',pm.model,' · ',pt.name,' · ',pv.name),
regexp_replace(unaccent(lower(concat_ws(' ',pm.brand,pm.model,pt.name,pv.name))),'\\s+',' ','g'),
true
from public.phone_models pm
cross join public.part_types pt
join public.part_variants pv on pv.part_type_id=pt.id
where pm.active=true and pt.active=true and pv.active=true
on conflict(phone_model_id,part_type_id,part_variant_id) do update
set display_name=excluded.display_name, normalized_search=excluded.normalized_search, active=true;

do $$ declare v_models integer; v_brands integer; begin select count(*),count(distinct brand) into v_models,v_brands from public.phone_models where active; if v_models < 109 or v_brands < 12 then raise exception 'Catálogo maestro incompleto: % modelos, % marcas',v_models,v_brands; end if; end $$;
